#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


TOTAL_STAGES=6

die() { printf '\nStopped: %s\n' "$*" >&2; exit 1; }
require_value() { [[ -n "$2" && "$2" != *$'\n'* && "$2" != *$'\r'* ]] || die "Invalid $1."; }
valid_release() { [[ "$1" =~ ^release-[0-9]{8}-[0-9]{2,}$ ]]; }
need() { command -v "$1" >/dev/null 2>&1 || die "Required command missing: $1"; }

main() {
  if [[ "${1:-}" == --help ]]; then
    printf 'Usage: bash epm-release-mac.sh\nInteractive build, bundle and IAP upload. No VM services are changed.\n'
    return
  fi
  [[ $# == 0 ]] || die "Use --help for usage."
  [[ "$(uname -s)" == Darwin ]] || die "Run this wizard on your Mac."
  [[ -t 0 && -t 1 ]] || die "Run interactively in a terminal."
  unset PYTHONPATH PYTHONHOME
  umask 077
  local repo application state_dir release bundle archive digest source_commit wheel python_path
  repo="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." && pwd)"
  application="$repo/application"
  state_dir="$HOME/Library/Application Support/EPM/release-wizard"
  mkdir -p "$state_dir"
  ENV_FILE="$state_dir/mac.env"
  banner "EPM · Mac release wizard"

  stage "Select a release and destination"
  for tool in git gcloud shasum tar; do need "$tool"; done
  ask EPM_RELEASE "New release ID (release-YYYYMMDD-NN):"
  valid_release "$EPM_RELEASE" || die "Use release-YYYYMMDD-NN, with at least two sequence digits."
  release="$EPM_RELEASE"
  ask EPM_PROJECT "Google project ID [blank: project-47b72bb7-ba90-42c9-910]:"
  EPM_PROJECT="${EPM_PROJECT:-project-47b72bb7-ba90-42c9-910}"
  ask EPM_VM "VM name [blank: epm-demo]:"
  EPM_VM="${EPM_VM:-epm-demo}"
  ask EPM_ZONE "VM zone [blank: us-west1-b]:"
  EPM_ZONE="${EPM_ZONE:-us-west1-b}"
  for value in "$EPM_PROJECT" "$EPM_VM" "$EPM_ZONE"; do
    [[ "$value" =~ ^[a-z0-9][a-z0-9-]*$ ]] || die "Invalid Google destination."
  done
  bundle="$application/dist/$release"
  archive="$application/dist/$release.tar.gz"
  [[ ! -e "$bundle" && ! -L "$bundle" && ! -e "$archive" && ! -L "$archive" ]] ||
    die "Release output already exists. Use a new ID; never overwrite a release."
  write_env EPM_RELEASE "$release"
  write_env EPM_PROJECT "$EPM_PROJECT"
  write_env EPM_VM "$EPM_VM"
  write_env EPM_ZONE "$EPM_ZONE"

  stage "Review source and tests"
  cd "$repo"
  git status --short
  [[ -z "$(git status --porcelain)" ]] || die "Commit intended changes and clear unintended changes first."
  source_commit="$(git rev-parse HEAD)"
  say "Source: $source_commit"
  confirm "Have the release's focused tests passed, and is this the intended source?" || die "Run/review tests first."
  ask EPM_TEST_EVIDENCE "Focused test results/evidence reference (required):"
  require_value "test evidence" "$EPM_TEST_EVIDENCE"

  stage "Build the wheel and compiled browser UI"
  confirm "Run build_wheel.sh (quality checks, frontend build and wheel packaging)?" || die "Build cancelled."
  "$application/scripts/build_wheel.sh"
  [[ "$(git rev-parse HEAD)" == "$source_commit" && -z "$(git status --porcelain)" ]] ||
    die "The source changed during build. Review and build a new recorded release."
  python_path="${EPM_PYTHON:-$application/.venv/bin/python}"
  if [[ ! -x "$python_path" ]]; then python_path="$repo/.venv/easy-property-management/bin/python"; fi
  [[ -x "$python_path" ]] || die "Set EPM_PYTHON to the build interpreter."
  wheel="$("$python_path" -c 'import tomllib; from pathlib import Path; p=tomllib.loads(Path("application/pyproject.toml").read_text())["project"]; print(p["name"].replace("-", "_")+"-"+p["version"]+"-py3-none-any.whl")')"
  [[ -f "$application/dist/$wheel" ]] || die "Built wheel not found."

  stage "Bundle matching resources without macOS sidecars"
  mkdir "$bundle"
  mkdir -p "$bundle/schema-resources/database"
  cp -X "$application/dist/$wheel" "$bundle/"
  cp -X "$application/alembic.ini" "$bundle/schema-resources/"
  cp -RX "$application/database/sqlite-migrations" "$bundle/schema-resources/database/"
  cp -X "$application/scripts/stage_schema_resources.py" "$application/scripts/verify_installation.py" "$bundle/"
  cp -X "$application/scripts/epm-release-vm.sh" "$bundle/release-vm.sh"
  printf '%s\n' "$source_commit" > "$bundle/SOURCE_COMMIT.txt"
  printf '%s\n' "$EPM_TEST_EVIDENCE" > "$bundle/TEST_EVIDENCE.txt"
  (
    cd "$bundle"
    find . -type f ! -path '*/__pycache__/*' ! -name '*.pyc' \
      ! -name '._*' ! -name '.DS_Store' ! -name SHA256SUMS \
      -exec shasum -a 256 {} \; > SHA256SUMS
    COPYFILE_DISABLE=1 tar --disable-copyfile --exclude='._*' --exclude='.DS_Store' \
      --exclude='__pycache__' --exclude='*.pyc' -czf "$archive" .
    shasum -a 256 --check SHA256SUMS
  )
  digest="$(shasum -a 256 "$archive")"
  digest="${digest%% *}"
  cp -X "$bundle/release-vm.sh" "$application/dist/$release-vm.sh"
  printf '%s  %s.tar.gz\n' "$digest" "$release" > "$application/dist/$release.tar.gz.sha256"
  write_env EPM_ARCHIVE_SHA256 "$digest"

  stage "Upload through IAP"
  say "Destination: $EPM_PROJECT / $EPM_ZONE / $EPM_VM"
  say "Archive SHA-256: $digest"
  confirm "Upload this archive and VM wizard to the administrator's VM home?" || die "Upload cancelled; bundle retained."
  gcloud compute ssh "$EPM_VM" --project="$EPM_PROJECT" --zone="$EPM_ZONE" \
    --tunnel-through-iap --command="test ! -e '$release.tar.gz' && test ! -e '$release-vm.sh'"
  gcloud compute scp "$archive" "$application/dist/$release-vm.sh" \
    "$application/dist/$release.tar.gz.sha256" "$EPM_VM:" \
    --project="$EPM_PROJECT" --zone="$EPM_ZONE" --tunnel-through-iap

  stage "VM handoff"
  say "Keep this independently computed SHA-256 for the VM wizard:"
  say "$digest"
  say "Connect on the Mac:"
  printf '  gcloud compute ssh %s --project=%s --zone=%s --tunnel-through-iap\n' "$EPM_VM" "$EPM_PROJECT" "$EPM_ZONE"
  say "Then run on the VM:"
  printf '  bash "$HOME/%s-vm.sh"\n' "$release"
  say "Choose Install, then run the VM wizard again for Deploy A and Deploy B."
  say "No VM service or workspace was changed by this Mac wizard."
  finish
}

main "$@"

